import{_ as a,o,c as e,ai as r}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"Grok Bot 0.71.2：一条消息能带 20 个附件，桌面端也能收提醒了","description":"","frontmatter":{"date":"2026-10-20T00:00:00.000Z","title":"Grok Bot 0.71.2：一条消息能带 20 个附件，桌面端也能收提醒了","summary":"官方更新日志 10 月 14 日的 0.71.2 里，对普通用户最有用的 6 处变化，以及每一条你今天就能怎么用。","category":"新闻简报","tags":["版本更新","附件","通知","插件"],"sources":[{"url":"https://x.ai/changelog/bot","author":"Grok Bot Changelog","platform":"官方更新日志"},{"url":"https://x.com/bot/status/2111184275374813362","author":"@bot","platform":"X"}],"updates":[{"link":"/faq/faq","title":"常见问题（新增 12 条）"}],"wordCount":749,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Grok Bot 0.71.2：一条消息能带 20 个附件，桌面端也能收提醒了 | WANGXXXL"}],["meta",{"property":"og:description","content":"官方更新日志 10 月 14 日的 0.71.2 里，对普通用户最有用的 6 处变化，以及每一条你今天就能怎么用。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-20-grok-bot-0-71-2"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-20-grok-bot-0-71-2-f1f2ecc88d.png"}],["meta",{"property":"og:image:alt","content":"Grok Bot 0.71.2：一条消息能带 20 个附件，桌面端也能收提醒了 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"Grok Bot 0.71.2：一条消息能带 20 个附件，桌面端也能收提醒了 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"官方更新日志 10 月 14 日的 0.71.2 里，对普通用户最有用的 6 处变化，以及每一条你今天就能怎么用。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-20-grok-bot-0-71-2-f1f2ecc88d.png"}],["meta",{"name":"twitter:image:alt","content":"Grok Bot 0.71.2：一条消息能带 20 个附件，桌面端也能收提醒了 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-20-grok-bot-0-71-2"}]]},"headers":[],"relativePath":"daily/2026-10-20-grok-bot-0-71-2.md","filePath":"daily/2026-10-20-grok-bot-0-71-2.md","lastUpdated":1792499664000}'),n={name:"daily/2026-10-20-grok-bot-0-71-2.md"};function i(l,t,s,c,p,d){return o(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="grok-bot-0-71-2-一条消息能带-20-个附件-桌面端也能收提醒了" tabindex="-1">Grok Bot 0.71.2：一条消息能带 20 个附件，桌面端也能收提醒了 <a class="header-anchor" href="#grok-bot-0-71-2-一条消息能带-20-个附件-桌面端也能收提醒了" aria-label="Permalink to &quot;Grok Bot 0.71.2：一条消息能带 20 个附件，桌面端也能收提醒了&quot;">​</a></h1><p>官方更新日志在 10 月 14 日发布了 0.71.2（同时包含 0.71.0 和 0.71.1）。改动有几十条，大部分是修 Bug，下面只挑<strong>普通用户马上能用上</strong>的 6 条，每条后面写了怎么用。</p><h2 id="_1-附件上限大幅提高" tabindex="-1">1. 附件上限大幅提高 <a class="header-anchor" href="#_1-附件上限大幅提高" aria-label="Permalink to &quot;1. 附件上限大幅提高&quot;">​</a></h2><ul><li>一条消息最多带 <strong>20 个附件</strong>（之前是 6 个），一条消息总大小 200 MB，超出的会提示有几个没加上。</li><li>单个文件最大 <strong>250 MB</strong>，视频最大 <strong>1 GB</strong>，视频太大看不了时 Bot 会直接说。需要 0.70.2 及以上版本。</li></ul><p><strong>怎么用</strong>：一个月的报销单、十几张截图，现在可以一次拖进去，让 Bot 一次性汇总：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是 10 月的 18 张报销截图。逐张读出日期、商户、金额、类别，</span></span>
<span class="line"><span>整理成一张 Excel，最后一行求和；看不清的单独列出来，不要猜。</span></span></code></pre></div><h2 id="_2-在电脑前时-提醒发到电脑上" tabindex="-1">2. 在电脑前时，提醒发到电脑上 <a class="header-anchor" href="#_2-在电脑前时-提醒发到电脑上" aria-label="Permalink to &quot;2. 在电脑前时，提醒发到电脑上&quot;">​</a></h2><p>用 Mac 或 Windows 时，Bot 的回复和提问会在电脑上提醒你，不再只推到手机。需要 0.70.2 及以上版本。审批卡片如果来自例程，大约 10 分钟没人处理就会过期，这条改动能少错过很多卡片。</p><h2 id="_3-插件技能上限从-24-个提到-200-个" tabindex="-1">3. 插件技能上限从 24 个提到 200 个 <a class="header-anchor" href="#_3-插件技能上限从-24-个提到-200-个" aria-label="Permalink to &quot;3. 插件技能上限从 24 个提到 200 个&quot;">​</a></h2><p>装了很多插件时，以前有些插件自带的技能会被&quot;挤掉&quot;，现在最多能用 200 个。之前觉得&quot;装了插件但 Bot 好像不会用&quot;的，可以更新后再试一次。</p><h2 id="_4-bot-自己的邮箱支持-带标签的地址" tabindex="-1">4. Bot 自己的邮箱支持&quot;带标签的地址&quot; <a class="header-anchor" href="#_4-bot-自己的邮箱支持-带标签的地址" aria-label="Permalink to &quot;4. Bot 自己的邮箱支持&quot;带标签的地址&quot;&quot;">​</a></h2><p>Bot 可以用 <code>名字+标签@</code> 这样的地址收发邮件，而且<strong>挂在某个标签上的例程只处理发到这个标签的邮件</strong>。比如订阅资讯用 <code>+news</code>，网站注册验证码用 <code>+signup</code>，互不干扰。详见今天的另一条日更：<a href="/daily/2026-10-20-bot-own-email">让 Bot 用自己的邮箱收验证码和订阅</a>。</p><h2 id="_5-磁盘快满时会先问你" tabindex="-1">5. 磁盘快满时会先问你 <a class="header-anchor" href="#_5-磁盘快满时会先问你" aria-label="Permalink to &quot;5. 磁盘快满时会先问你&quot;">​</a></h2><p>Bot 的云电脑磁盘不够时，它会提醒一次、列出最大的几个文件，<strong>你同意后才删</strong>。</p><h2 id="_6-语音通话断线会自动重连" tabindex="-1">6. 语音通话断线会自动重连 <a class="header-anchor" href="#_6-语音通话断线会自动重连" aria-label="Permalink to &quot;6. 语音通话断线会自动重连&quot;">​</a></h2><p>语音聊天掉线后会重连并继续同一段对话，不会直接挂断；用手机发起的语音通话也会唤醒正在休眠的云电脑。</p><h2 id="同期官方消息-整体提速" tabindex="-1">同期官方消息：整体提速 <a class="header-anchor" href="#同期官方消息-整体提速" aria-label="Permalink to &quot;同期官方消息：整体提速&quot;">​</a></h2><p>官方账号 <a href="https://x.com/bot/status/2111184275374813362" target="_blank" rel="noopener noreferrer">@bot</a> 10 月 17 日（UTC+8）发帖说：电脑类任务平均快 3 倍完成，其他回复的等待时间不到原来的一半。这是官方给的平均数，没有公布测试方法；浏览器操作多的任务感受通常最明显，以你自己的任务实测为准。同一组帖子里还提到语音通话更快、更稳，也更能记住之前聊过的内容。</p><h2 id="怎么确认自己是不是新版本" tabindex="-1">怎么确认自己是不是新版本 <a class="header-anchor" href="#怎么确认自己是不是新版本" aria-label="Permalink to &quot;怎么确认自己是不是新版本&quot;">​</a></h2><p>在账户菜单里打开 <strong>Support → About</strong> 可以看到版本号。桌面端默认开启自动更新，如果你关掉过，记得在设置的「更新」里手动检查。</p>`,20)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
